<?php
namespace App\Models;
use App\Enums\GiftCardStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
class GiftCard extends Model { protected $fillable=['code_hash','code_last_four','currency_code','initial_amount','recipient_user_id','recipient_name','recipient_email','message','status','expires_at','issued_at','issued_by']; protected function casts():array{return ['status'=>GiftCardStatus::class,'initial_amount'=>'integer','expires_at'=>'datetime','issued_at'=>'datetime'];} public function transactions():HasMany{return $this->hasMany(GiftCardTransaction::class);} public function recipient(){return $this->belongsTo(User::class,'recipient_user_id');} public function balance():int{return (int)$this->transactions()->get(['amount','type'])->sum(fn($t)=>in_array($t->type->value,['issue','refund','adjustment'],true)?$t->amount:-$t->amount);} public function usable():bool{return $this->status===GiftCardStatus::Active && (!$this->expires_at||$this->expires_at->isFuture()) && $this->balance()>0;} }
